export const isEmptyArray = (arrayItem): boolean => {
  let emptyArray = true;

  if (Array.isArray(arrayItem) && arrayItem.length > 0) {
    emptyArray = false;
  }

  return emptyArray;
};

export const getFirstItem = (arrayItem): Record<string, unknown> => {
  let firstItem = {};

  if (isNonEmptyArray(arrayItem) && !isEmpty(arrayItem[0])) {
    firstItem = arrayItem[0];
  }

  return firstItem;
};

export const getLastItem = (arrayItem): Record<string, unknown> => {
  let lastItem = {};

  if (isNonEmptyArray(arrayItem) && !isEmpty(arrayItem[arrayItem.length - 1])) {
    lastItem = arrayItem[arrayItem.length - 1];
  }

  return lastItem;
};

export const displayValue = (variableValue): string => {
  let displayValue = "";

  if (!isEmpty(variableValue)) {
    if (variableValue === true) {
      displayValue = "True";
    } else if (variableValue === false) {
      displayValue = "False";
    } else if (variableValue instanceof Date) {
      displayValue = variableValue.toLocaleString();
    } else {
      displayValue = variableValue;
    }
  } else {
    displayValue = "Value is undefined or null.";
  }

  return displayValue;
};

