export const convertSpecialCharacters = (value): string => {
  // * https://stackoverflow.com/questions/1787322/what-is-the-htmlspecialchars-equivalent-in-javascript/4835406#4835406 -- 12/28/2021 MF

  let newValue = value;

  if (!isEmpty(value)) {
    newValue = newValue.replace(/&/g, "&amp;");
    newValue = newValue.replace(/</g, "&lt;");
    newValue = newValue.replace(/>/g, "&gt;");
    newValue = newValue.replace(/"/g, "&quot;");
    newValue = newValue.replace(/'/g, "&#039;");
  }

  return newValue;
};

export const truncateText = (text, limit): string => {
  // * https://stackoverflow.com/questions/4700226/i-want-to-truncate-a-text-or-line-with-ellipsis-using-javascript -- 03/06/2021 MF

  if (!isEmpty(text) && text.length > limit) {
    for (let i = limit; i > 0; i--) {
      if (
        text.charAt(i) === " " &&
        (text.charAt(i - 1) !== "," || text.charAt(i - 1) !== "." || text.charAt(i - 1) !== ";")
      ) {
        return text.substring(0, i) + "...";
      }
    }

    return text.substring(0, limit) + "...";
  } else {
    return text;
  }
};

export const validateMilitaryTime = (timeEntered): boolean => {
  // * Time in 24 clock, no colon -- 03/05/2021 MF

  // * all digits-- 03/05/2021 MF
  // * length is 4
  // * first digit is either a 0 or 1 or 2
  // * second digit is either a 0 or 1 or 2 or 3 or 4 or 5
  // * third digit is either a 0 or 1 or 2 or 3 or 4 or 5

  // * Make sure that it is a string-- 03/05/2021 MF

  let validTimeFormat = true;

  let timeEnteredString = "";

  if (typeof formatToString(timeEntered) === "string") {
    timeEnteredString = formatToString(timeEntered);

    timeEnteredString = timeEnteredString.trim();

    if (timeEnteredString.length !== 4) {
      validTimeFormat = false;
    } else {
      if (
        isNaN(parseInt(timeEnteredString.charAt(0))) ||
        isNaN(parseInt(timeEnteredString.charAt(1))) ||
        isNaN(parseInt(timeEnteredString.charAt(2))) ||
        isNaN(parseInt(timeEnteredString.charAt(3)))
      ) {
        validTimeFormat = false;
      }

      if (
        timeEnteredString.charAt(0) !== "0" &&
        timeEnteredString.charAt(0) !== "1" &&
        timeEnteredString.charAt(0) !== "2"
      ) {
        validTimeFormat = false;
      }

      if (
        timeEnteredString.charAt(0) === "2" &&
        timeEnteredString.charAt(1) !== "0" &&
        timeEnteredString.charAt(1) !== "1" &&
        timeEnteredString.charAt(1) !== "2" &&
        timeEnteredString.charAt(1) !== "3" &&
        timeEnteredString.charAt(1) !== "4"
      ) {
        validTimeFormat = false;
      }

      if (
        timeEnteredString.charAt(0) === "2" &&
        timeEnteredString.charAt(1) !== "4" &&
        timeEnteredString.charAt(2) !== "0" &&
        timeEnteredString.charAt(3) !== "0"
      ) {
        validTimeFormat = false;
      }

      if (
        timeEnteredString.charAt(2) !== "0" &&
        timeEnteredString.charAt(2) !== "1" &&
        timeEnteredString.charAt(2) !== "2" &&
        timeEnteredString.charAt(2) !== "3" &&
        timeEnteredString.charAt(2) !== "4" &&
        timeEnteredString.charAt(2) !== "5"
      ) {
        validTimeFormat = false;
      }
    }
  } else {
    validTimeFormat = false;
  }

  return validTimeFormat;
};

export const convertTemperature = (temperatureScale, temperature): string => {
  // let temperatureFloat = parseFloat(formatTrim(temperature));
  const temperatureFloat = parseFloat(temperature);
  let temperatureConverted = "";

  if (!isEmpty(temperatureFloat) && !isNaN(temperatureFloat)) {
    if (formatLowerCase(temperatureScale) === "celsius") {
      // * Based on (32°F - 32) x 5/9 = 0°C -- 07/29/2021 MF
      temperatureConverted = (((temperatureFloat - 32) * 5) / 9).toFixed(2);
    } else if (formatLowerCase(temperatureScale) === "fahrenheit") {
      // * Based on (32°F - 32) x 5/9 = 0°C -- 07/29/2021 MF
      temperatureConverted = ((temperatureFloat * 9) / 5 + 32).toFixed(2);
    }
  } else {
    temperatureConverted = "";
  }

  return temperatureConverted;
};

