export const addLog = (
  baseURL,
  fetchAuthorization,
  databaseAvailable,
  allowLogging,
  logObject
): string => {
  let logResult = "Add log not attempted due to parameter values.";

  if (allowLogging === true && databaseAvailable !== false) {
    const operation = "Add Log";

    const url = `${baseURL}logs/`;
    let response: Response;
    let data = "";

    fetch(url, {
      method: "POST",
      headers: new Headers({
        "Content-Type": "application/json",
        Authorization: fetchAuthorization
      }),
      body: JSON.stringify({ recordObject: logObject })
    })
      .then(results => {
        response = results;

        if (response.status === 200) {
          return response.json();
        } else {
          addErrorLog(baseURL, fetchAuthorization, databaseAvailable, allowLogging, {
            operation: `${operation} SQL Server`,
            transactionData: {
              url,
              response: {
                ok: response.ok,
                redirected: response.redirected,
                status: response.status,
                statusText: response.statusText,
                type: response.type,
                url: response.url
              },
              data,
              logObject: logObject
            },
            errorData: { message: `${response.status} ${response.statusText} ${response.url}` },
            dateEntered: getDateTime()
          });

          logResult = `${operation}: ${response.status} ${response.statusText} ${response.url}`;
        }
      })
      .then(results => {
        data = results;

        logResult = results;
      })
      .catch(error => {
        // console.error("addLog error", error);
        // console.error("addLog error.name", error.name);
        // console.error("addLog error.message", error.message);
        // console.error("addLog error.stack", error.stack);

        // dispatch(addErrorMessage(`${operation}: ${convertSpecialCharacters(error.name)}: ${convertSpecialCharacters(error.message)}`));

        addErrorLog(baseURL, fetchAuthorization, databaseAvailable, allowLogging, {
          operation,
          transactionData: {
            url,
            response: {
              ok: response.ok,
              redirected: response.redirected,
              status: response.status,
              statusText: response.statusText,
              type: response.type,
              url: response.url
            },
            data,
            logObject
          },
          errorData: { name: error.name, message: error.message, stack: error.stack },
          dateEntered: getDateTime()
        });

        logResult = `${operation}: ${convertSpecialCharacters(error.name)}: ${convertSpecialCharacters(error.message)}`;
      });
  }

  return logResult;
};

