export const parse = (value, options: HTMLReactParserOptions) => {
  // * The parseHTML function from the npm package html-react-parser doesn't provide error handling if the value sent to it isn't a string. -- 03/09/2023 MF

  let newValue = value;

  if (!isEmpty(value)) {
    if (!isEmpty(options)) {
      // @ts-expect-error html-react-parser default import is callable at runtime but typed here as a module object
      newValue = parseHTML(value, options);
    } else {
      // @ts-expect-error html-react-parser default import is callable at runtime but typed here as a module object
      newValue = parseHTML(value);
    }
  }

  return newValue;
};

