export const getNumberOfDaysBetweenDates = (startDate, endDate): number => {
  // * https://www.geeksforgeeks.org/how-to-calculate-the-number-of-days-between-two-dates-in-javascript/ -- 09/12/2023 KH
  // * https://stackoverflow.com/questions/2627473/how-to-calculate-the-number-of-days-between-two-dates/2627493#2627493 -- 09/12/2023 KH

  const newStartDate = new Date(startDate);
  const newEndDate = new Date(endDate);
  let numberOfDays = 1;

  // * The function getTime() converts days to milliseconds to subtract the two dates. -- 08/31/2023 KH
  // * The equation (1000 * 60 * 60 * 24) turns the values back into a day count. -- 08/31/2023 KH
  // * The operation + 1 adds one day to account for 08/31/2023 - 08/31/2023 = 0 but should equal 1 day in order to account for running studentsPerDay amount of students that day. -- 08/31/2023 KH
  numberOfDays = (newEndDate.getTime() - newStartDate.getTime()) / (1000 * 60 * 60 * 24) + 1;

  return numberOfDays;
};

export const convertTimeToMinutes = timeEntered => {
  // * https://stackoverflow.com/questions/32885682/convert-hhmmss-into-minute-using-javascript -- 11/27/2023 KH
  // * timeEntered must be a string in HH:MM format. -- 09/18/2023 KH

  const newTime = timeEntered.split(":");

  const minutes = +newTime[0] * 60 + +newTime[1];

  return minutes;
};

export const generateHoursInterval = (
  startHourInMinutes,
  endHourInMinutes,
  interval
): { timeID: number; time: string }[] => {
  // * https://gist.github.com/indexzero/6261ad9292c78cf3c5aa69265e2422bf?permalink_comment_id=4003346#gistcomment-4003346 -- 11/20/2023 KH

  const timesArray: { timeID: number; time: string }[] = [];

  if (!isEmpty(startHourInMinutes) && isWholeNumber(startHourInMinutes)) {
    for (let i = 0; startHourInMinutes < 24 * 60; i++) {
      if (startHourInMinutes > endHourInMinutes) {
        break;
      } else {
        // * Get hours of day in 0-24 format. -- 11/20/2023 KH
        const hh = Math.floor(startHourInMinutes / 60);

        // * Get minutes of the hour in 0-55 format. -- 11/20/2023 KH
        const mm = startHourInMinutes % 60;

        timesArray[i] = {
          timeID: i,
          time: convertMilitaryTimeToStandardTime(
            ("0" + (hh % 24)).slice(-2) + ":" + ("0" + mm).slice(-2)
          )
        };

        startHourInMinutes = startHourInMinutes + interval;
      }
    }
  }

  return timesArray;
};

export const displayCommaBetweenTwoItems = (firstItem, secondItem): string => {
  let textValue = "";

  if (!isEmpty(firstItem)) {
    textValue = firstItem;
  }

  if (!isEmpty(firstItem) && !isEmpty(secondItem)) {
    textValue += ", ";
  }

  if (!isEmpty(secondItem)) {
    textValue += secondItem;
  }

  return textValue;
};

export const constructCSVFile = (dataList, dataColumnTitles, propertyNameList): string => {
  let fileData = "";

  // * Initialize fileData with columns titles. -- 10/15/2024 EBG
  if (!isEmpty(dataColumnTitles)) {
    fileData += dataColumnTitles;
  }

  if (isNonEmptyArray(dataList) && isNonEmptyArray(propertyNameList)) {
    // * Loop through every record in the data. -- 10/16/2024 EBG
    for (let i = 0; i < dataList.length; i++) {
      // * Look at each object property name specified in propertyNameList. -- 10/16/2024 EBG
      for (let j = 0; j < propertyNameList.length; j++) {
        let cellData = "";

        const propertyNameData = dataList[i][propertyNameList[j].propertyName];

        if (!isEmpty(propertyNameData)) {
          // ? Will json need its own case or be passed as a string? -- 10/17/2024 EBG
          // * When JSON is passed, I'm pretty sure it's going to be a different case in these if statements. -- 10/17/2024 MF
          if (propertyNameList[j].dataType === "string") {
            cellData = `"${propertyNameData}"`;
          } else if (propertyNameList[j].dataType === "number") {
            cellData = `${propertyNameData}`;
          } else if (propertyNameList[j].dataType === "boolean") {
            cellData = `${propertyNameData === true || propertyNameData === 1 ? "Yes" : "-"}`;
          } else if (propertyNameList[j].dataType === "date") {
            cellData = `${displayDate(propertyNameData)}`;
          } else if (propertyNameList[j].dataType === "dateTime") {
            cellData = `${displayDateAndTime(propertyNameData)}`;
          } else if (propertyNameList[j].dataType === "hyperlink") {
            // * Creates a hyperlink in the CSV file. -- 05/30/2024 MF
            // * https://stackoverflow.com/questions/7572268/how-to-encode-a-hyperlink-in-csv-formatted-file -- 05/30/2024 MF

            cellData = "=HYPERLINK(" + `${propertyNameData}` + ")";
          }
        }

        fileData += `${cellData},`;
      }

      fileData += `\r\n`;
    }
  }

  return fileData;
};

export const exportCSVFile = (fileData, fileTitle): void => {
  // * https://medium.com/@gb.usmanumar/how-to-export-data-to-csv-json-in-react-js-ea45d940652a -- 05/30/2024 EBG

  const csvData = new Blob([fileData], { type: "text/csv" });
  const csvURL = window.URL.createObjectURL(csvData);
  const link = document.createElement("a");

  link.href = csvURL;
  link.download = `${fileTitle} ${displayDate(getDateTime()).replaceAll("/", "_")}.csv`;

  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
};

