export const createDateFromString = dateString => {
  let [year, month, day] = dateString.split("-").map(Number);

  if (dateString.includes("/")) {
    [month, day, year] = dateString.split("/").map(Number);
  }

  return new Date(year, month - 1, day); // * Month is 0-indexed. -- 04/08/2025 MF
};

export const isFutureDate = (dateToCheck, referenceDate) => {
  const dateOne = new Date(
    dateToCheck.getFullYear(),
    dateToCheck.getMonth(),
    dateToCheck.getDate()
  );

  const dateTwo = new Date(
    referenceDate.getFullYear(),
    referenceDate.getMonth(),
    referenceDate.getDate()
  );

  return dateOne > dateTwo;
};

export const formatToUSD = value => {
  if (!Number.isNaN(value)) {
    const formattedValue = new Intl.NumberFormat("en-US", {
      style: "currency",
      currency: "USD",
      maximumFractionDigits: 0
    }).format(value);

    return formattedValue;
  } else {
    return "";
  }
};

export const getYears = (months): string => {
  const parsedMonths = Number.parseFloat(months);

  if (Number.isNaN(parsedMonths)) return "";

  return (parsedMonths / 12).toFixed(1);
};

